def recolor_by_seed_graph(arr,target,seedvals,tie_orig=True, sources_are_pixels=True):
 # BFS from target cells adjacent to seedvals, for each seed color
 pred=arr.copy(); d_by={}
 for col in seedvals:
  starts=set()
  for r,c in map(tuple,np.argwhere(arr==target)):
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    x,y=r+dr,c+dc
    if 0<=x<arr.shape[0] and 0<=y<arr.shape[1] and arr[x,y]==col: starts.add((int(r),int(c)))
  ds={p:0 for p in starts};q=deque(starts)
  while q:
   r,c=q.popleft()
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    p=(r+dr,c+dc)
    if 0<=p[0]<arr.shape[0] and 0<=p[1]<arr.shape[1] and arr[p]==target and p not in ds:
     ds[p]=ds[(r,c)]+1;q.append(p)
  d_by[col]=ds
 for r,c in map(tuple,np.argwhere(arr==target)):
  ds=[d_by[col].get((int(r),int(c)),10**6) for col in seedvals]
  m=min(ds); who=[col for col,d in zip(seedvals,ds) if d==m]
  if len(who)==1 and m<10**6:pred[r,c]=who[0]
 return pred,d_by
