   p=q.pop();co.append(p)
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    t=(p[0]+dr,p[1]+dc)
    if 0<=t[0]<arr.shape[0] and 0<=t[1]<arr.shape[1] and t not in seen and arr[t]!=target:seen.add(t);q.append(t)
  idx=len(comps);comps.append(co)
  for p in co:compids[p]=idx
 # collect source labels per component; dominant value in component excluding baseline color(s) if set
 src_comps={}
