def propagate_label_regions(arr,target,ignore=(None,)):
 # non-target connected components as labeled sources; use modal color after dropping background colors
 src_comps=[]; seen=set(); comps_nt=[]
 for r,c in map(tuple,np.argwhere(arr!=target)):
  r=int(r);c=int(c)
  if (r,c) in seen:continue
  q=[(r,c)];seen.add((r,c));co=[]
  while q:
   p=q.pop();co.append(p)
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    n=(p[0]+dr,p[1]+dc)
    if 0<=n[0]<arr.shape[0] and 0<=n[1]<arr.shape[1] and n not in seen and arr[n]!=target:
     seen.add(n);q.append(n)
  comps_nt.append(co)
 for i,co in enumerate(comps_nt):
  hist=Counter(int(arr[p]) for p in co if int(arr[p]) not in ignore)
  if not hist:continue
  m=max(hist.values());labs=[k for k,v in hist.items() if v==m]
  if len(labs)==1:
   src_comps.append((i,labs[0],co,hist))
 labels={col for _,col,_,_ in src_comps};dist_by={}
 for col in labels:
  starts=set()
  for i,color,co,hist in src_comps:
   if color!=col:continue
   for r,c in co:
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(r+dr,c+dc)
     if 0<=p[0]<arr.shape[0] and 0<=p[1]<arr.shape[1] and arr[p]==target:starts.add(p)
  ds={p:0 for p in starts};q=deque(starts)
  while q:
   r,c=q.popleft()
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    p=(r+dr,c+dc)
    if 0<=p[0]<arr.shape[0] and 0<=p[1]<arr.shape[1] and arr[p]==target and p not in ds:ds[p]=ds[(r,c)]+1;q.append(p)
  dist_by[col]=ds
 pred=arr.copy()
 for r,c in map(tuple,np.argwhere(arr==target)):
  valdist={lab:d.get((int(r),int(c)),10**6) for lab,d in dist_by.items()}
  best=min(valdist.values())
  winners=[lab for lab,d in valdist.items() if d==best]
  if best<10**6 and len(winners)==1: pred[r,c]=winners[0]
 return pred,src_comps,dist_by
